  briefing_minutes             NUMERIC,
  shift_hours                  NUMERIC,
  break_policy                 TEXT,
  supervisor_required          BOOLEAN,
  rate                         BIGINT,
  rate_unit                    TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_guest_services_items_service ON public.partner_guest_services_items (service_id, position);

ALTER TABLE public.partner_guest_services_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS partner_guest_services_items_owner ON public.partner_guest_services_items;
CREATE POLICY partner_guest_services_items_owner ON public.partner_guest_services_items FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_guest_services_items.vendor_id AND v.profile_id = auth.uid()))
  WITH CHECK (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_guest_services_items.vendor_id AND v.profile_id = auth.uid()));

DROP POLICY IF EXISTS partner_guest_services_items_operator ON public.partner_guest_services_items;
CREATE POLICY partner_guest_services_items_operator ON public.partner_guest_services_items FOR ALL TO authenticated
  USING (public.caller_is_operator()) WITH CHECK (public.caller_is_operator());

COMMIT;

